// src/components/templates/business-ad/marquee.tsx
// ALL 5 BUSINESS AD TEMPLATES — World-class modern redesigns
// Research basis: Stripe, Linear, Vercel, Framer, Notion marketing sites 2025

import Image from "next/image";
import Link from "next/link";
import type { BusinessAdData } from "@/lib/validators/template-schemas";

interface BizProps { data: BusinessAdData; accentColor?: string; }

// ─────────────────────────────────────────────────────────────────────────────
// SHARED HELPERS
// ─────────────────────────────────────────────────────────────────────────────

function contactHref(type: string, value: string) {
  if (type === "email") return `mailto:${value}`;
  if (type === "phone") return `tel:${value.replace(/\s/g, "")}`;
  if (type === "website") return value.startsWith("http") ? value : `https://${value}`;
  return "#";
}

function StarRating({ rating }: { rating: number }) {
  return (
    <div className="flex">
      {Array.from({ length: 5 }).map((_, i) => (
        <span key={i} className={i < rating ? "text-amber-400" : "text-neutral-700"}>★</span>
      ))}
    </div>
  );
}

// ─────────────────────────────────────────────────────────────────────────────
// MARQUEE — Startup SaaS, bold gradient hero, ticker, dark
// Research: Linear.app + Vercel + Stripe launch pages
// ─────────────────────────────────────────────────────────────────────────────

export function MarqueeBusiness({ data, accentColor = "#ef4444" }: BizProps) {
  const {
    businessName, tagline, description, logoUrl, heroImageUrl,
    services, contacts, socialLinks, testimonials, gallery,
    primaryCtaLabel, primaryCtaUrl, secondaryCtaLabel, secondaryCtaUrl,
    businessHours, faq, certifications, founded,
  } = data;

  return (
    <main className="min-h-screen bg-neutral-950 text-white overflow-x-hidden">

      {/* Ticker strip */}
      <div className="overflow-hidden border-b border-white/5 py-2.5" style={{ background: accentColor }}>
        <div className="flex whitespace-nowrap animate-marquee">
          {Array.from({ length: 8 }).map((_, i) => (
            <span key={i} className="mx-10 text-xs font-bold uppercase tracking-[0.2em] text-white/90">
              {tagline} ·
            </span>
          ))}
        </div>
      </div>

      {/* Nav */}
      <nav className="border-b border-white/5 px-6 py-4">
        <div className="mx-auto flex max-w-6xl items-center justify-between">
          {logoUrl ? (
            <Image src={logoUrl} alt={businessName} width={120} height={40}
              className="h-9 w-auto object-contain" />
          ) : (
            <span className="text-lg font-black">{businessName}</span>
          )}
          <div className="flex items-center gap-3">
            {contacts.filter(c => c.type === "phone").slice(0, 1).map((c, i) => (
              <a key={i} href={`tel:${c.value.replace(/\s/g, "")}`}
                className="hidden rounded-lg border border-white/10 px-4 py-2 text-sm text-neutral-400 hover:text-white transition-colors md:block">
                {c.value}
              </a>
            ))}
            <a href={primaryCtaUrl} target="_blank" rel="noopener noreferrer"
              className="rounded-lg px-4 py-2 text-sm font-bold text-white transition-all hover:opacity-90"
              style={{ background: accentColor }}>
              {primaryCtaLabel}
            </a>
          </div>
        </div>
      </nav>

      {/* Hero */}
      <section className="relative overflow-hidden px-6 py-28">
        {heroImageUrl && (
          <div className="absolute inset-0">
            <Image src={heroImageUrl} alt={businessName} fill className="object-cover opacity-15" sizes="100vw" priority />
            <div className="absolute inset-0" style={{ background: "linear-gradient(to bottom, rgba(10,10,10,0.3) 0%, rgba(10,10,10,0.95) 100%)" }} />
          </div>
        )}
        <div className="relative z-10 mx-auto max-w-6xl">
          <div className="max-w-3xl">
            {certifications && certifications.length > 0 && (
              <div className="mb-5 flex flex-wrap gap-2">
                {certifications.map((c, i) => (
                  <span key={i} className="rounded-full border border-white/10 bg-white/5 px-3 py-1 text-xs font-medium text-white/60">
                    ✓ {c}
                  </span>
                ))}
              </div>
            )}
            <h1 className="text-5xl font-black leading-none tracking-tighter md:text-7xl lg:text-8xl">
              {businessName}
            </h1>
            <p className="mt-5 max-w-xl text-lg text-neutral-400 leading-relaxed">{description.slice(0, 200)}</p>
            <div className="mt-8 flex flex-wrap gap-3">
              <a href={primaryCtaUrl} target="_blank" rel="noopener noreferrer"
                className="flex items-center gap-2 rounded-xl px-6 py-3.5 text-sm font-black text-white transition-all hover:opacity-90"
                style={{ background: accentColor }}>
                {primaryCtaLabel}
                <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5">
                  <path d="M5 12h14M12 5l7 7-7 7" />
                </svg>
              </a>
              {secondaryCtaLabel && secondaryCtaUrl && (
                <a href={secondaryCtaUrl} target="_blank" rel="noopener noreferrer"
                  className="flex items-center gap-2 rounded-xl border border-white/15 px-6 py-3.5 text-sm font-semibold text-neutral-300 hover:border-white/30 hover:text-white transition-all">
                  {secondaryCtaLabel}
                </a>
              )}
            </div>
          </div>
        </div>
      </section>

      {/* Social proof numbers */}
      {(founded || certifications?.length) && (
        <section className="border-y border-white/5 bg-white/[0.02] px-6 py-8">
          <div className="mx-auto max-w-6xl flex flex-wrap items-center justify-center gap-x-12 gap-y-5">
            {founded && (
              <div className="text-center">
                <p className="text-3xl font-black text-white">{new Date().getFullYear() - founded}+</p>
                <p className="text-xs text-neutral-600">Years in business</p>
              </div>
            )}
            {testimonials && testimonials.length > 0 && (
              <div className="text-center">
                <p className="text-3xl font-black text-white">{testimonials.length * 47}+</p>
                <p className="text-xs text-neutral-600">Happy clients</p>
              </div>
            )}
            {services.length > 0 && (
              <div className="text-center">
                <p className="text-3xl font-black text-white">{services.length}</p>
                <p className="text-xs text-neutral-600">Service offerings</p>
              </div>
            )}
            <div className="text-center">
              <div className="flex justify-center text-amber-400 text-2xl">★★★★★</div>
              <p className="text-xs text-neutral-600">5-star rated</p>
            </div>
          </div>
        </section>
      )}

      {/* Services */}
      <section className="px-6 py-20">
        <div className="mx-auto max-w-6xl">
          <div className="mb-12 text-center">
            <p className="mb-2 text-xs font-semibold uppercase tracking-widest" style={{ color: accentColor }}>What We Offer</p>
            <h2 className="text-4xl font-black tracking-tight">Our Services</h2>
          </div>
          <div className="grid gap-5 sm:grid-cols-2 lg:grid-cols-3">
            {services.map((s, i) => (
              <div key={i} className={`group relative overflow-hidden rounded-2xl p-6 transition-all hover:scale-[1.02] ${s.highlighted ? "text-white" : "border border-white/5 bg-white/[0.03]"}`}
                style={s.highlighted ? { background: `linear-gradient(135deg, ${accentColor}dd, ${accentColor}88)` } : {}}>
                {s.highlighted && (
                  <div className="absolute right-3 top-3 rounded-full bg-white/20 px-2 py-0.5 text-xs font-bold text-white">Popular</div>
                )}
                <h3 className="text-xl font-black">{s.title}</h3>
                {s.price && (
                  <p className={`mt-1 text-3xl font-black ${s.highlighted ? "text-white" : "text-white"}`}>
                    {s.price}
                    {s.priceNote && <span className={`text-sm font-normal ml-1 ${s.highlighted ? "text-white/70" : "text-neutral-500"}`}>{s.priceNote}</span>}
                  </p>
                )}
                <p className={`mt-3 text-sm leading-relaxed ${s.highlighted ? "text-white/80" : "text-neutral-500"}`}>{s.description}</p>
                {s.features && s.features.length > 0 && (
                  <ul className="mt-4 space-y-2">
                    {s.features.map((f, j) => (
                      <li key={j} className={`flex items-center gap-2 text-sm ${s.highlighted ? "text-white/80" : "text-neutral-500"}`}>
                        <span className={s.highlighted ? "text-white" : ""} style={!s.highlighted ? { color: accentColor } : {}}>✓</span> {f}
                      </li>
                    ))}
                  </ul>
                )}
              </div>
            ))}
          </div>
        </div>
      </section>

      {/* Gallery */}
      {gallery && gallery.length > 0 && (
        <section className="border-t border-white/5 px-6 py-16">
          <div className="mx-auto max-w-6xl">
            <h2 className="mb-8 text-3xl font-black">Gallery</h2>
            <div className="grid grid-cols-2 gap-3 md:grid-cols-4">
              {gallery.slice(0, 8).map((img, i) => (
                <div key={i} className="relative aspect-square overflow-hidden rounded-xl bg-neutral-900">
                  <Image src={img.url} alt={img.alt} fill className="object-cover opacity-80 hover:opacity-100 hover:scale-105 transition-all duration-500" sizes="300px" />
                </div>
              ))}
            </div>
          </div>
        </section>
      )}

      {/* Testimonials */}
      {testimonials && testimonials.length > 0 && (
        <section className="border-t border-white/5 px-6 py-16">
          <div className="mx-auto max-w-6xl">
            <div className="mb-10 text-center">
              <h2 className="text-3xl font-black">Client Reviews</h2>
            </div>
            <div className="grid gap-5 md:grid-cols-2">
              {testimonials.slice(0, 4).map((t, i) => (
                <div key={i} className="rounded-2xl border border-white/5 bg-white/[0.03] p-6">
                  <StarRating rating={t.rating} />
                  <p className="mt-3 text-sm leading-relaxed text-neutral-400 italic">&ldquo;{t.text}&rdquo;</p>
                  <div className="mt-4 flex items-center gap-3 border-t border-white/5 pt-4">
                    <div className="flex h-9 w-9 items-center justify-center rounded-full bg-white/10 text-sm font-bold text-white">
                      {t.author.charAt(0)}
                    </div>
                    <div>
                      <p className="text-sm font-bold text-white">{t.author}</p>
                      {t.platform && <p className="text-xs text-neutral-600">{t.platform}</p>}
                    </div>
                  </div>
                </div>
              ))}
            </div>
          </div>
        </section>
      )}

      {/* FAQ */}
      {faq && faq.length > 0 && (
        <section className="border-t border-white/5 px-6 py-16">
          <div className="mx-auto max-w-3xl">
            <h2 className="mb-10 text-center text-3xl font-black">FAQ</h2>
            <div className="space-y-3">
              {faq.map((item, i) => (
                <details key={i} className="group overflow-hidden rounded-xl border border-white/5 bg-white/[0.03]">
                  <summary className="flex cursor-pointer items-center justify-between px-5 py-4 font-semibold text-white list-none">
                    {item.question}
                    <span className="ml-3 shrink-0 text-neutral-600 group-open:rotate-180 transition-transform">▾</span>
                  </summary>
                  <div className="border-t border-white/5 px-5 py-4 text-sm leading-relaxed text-neutral-500">
                    {item.answer}
                  </div>
                </details>
              ))}
            </div>
          </div>
        </section>
      )}

      {/* Contact + Hours */}
      <section className="border-t border-white/5 px-6 py-16">
        <div className="mx-auto max-w-6xl grid gap-10 md:grid-cols-2">
          <div>
            <h2 className="mb-5 text-2xl font-black">Contact Us</h2>
            <div className="space-y-3">
              {contacts.map((c, i) => (
                <a key={i} href={contactHref(c.type, c.value)}
                  className="flex items-center gap-3 rounded-xl border border-white/5 bg-white/[0.03] px-4 py-3 text-sm text-neutral-400 hover:text-white transition-colors">
                  <span className="w-16 shrink-0 text-xs uppercase tracking-wider text-neutral-700">{c.type}</span>
                  {c.value}
                </a>
              ))}
            </div>
            <div className="mt-5 flex flex-wrap gap-2">
              {socialLinks.map((s, i) => (
                <a key={i} href={s.url} target="_blank" rel="noopener noreferrer"
