                  {s.label ?? s.platform}
                </a>
              ))}
            </div>
          </div>
          {businessHours && businessHours.length > 0 && (
            <div>
              <h2 className="mb-5 text-2xl font-black">Hours</h2>
              <div className="space-y-2 rounded-xl border border-white/5 bg-white/[0.03] p-4">
                {businessHours.map((h, i) => (
                  <div key={i} className="flex justify-between py-1.5 text-sm border-b border-white/5 last:border-0">
                    <span className="text-neutral-500">{h.day}</span>
                    <span className={h.isClosed ? "text-neutral-700" : "text-white"}>
                      {h.isClosed ? "Closed" : `${h.open} – ${h.close}`}
                    </span>
                  </div>
                ))}
              </div>
            </div>
