// ─────────────────────────────────────────────────────────────────────────────
// DISTRICT — Local business, warm & trustworthy, high-converting
// Research: Square, Toast POS, Booksy local business pages
// ─────────────────────────────────────────────────────────────────────────────

export function DistrictBusiness({ data, accentColor = "#0284c7" }: BizProps) {
  const {
    businessName, tagline, description, logoUrl, heroImageUrl,
    services, contacts, testimonials, businessHours, faq,
    primaryCtaLabel, primaryCtaUrl, address, socialLinks, certifications,
  } = data;

  return (
    <main className="min-h-screen bg-slate-50 text-slate-900">

      {/* Sticky header */}
      <header className="sticky top-0 z-50 border-b border-slate-200 bg-white/95 backdrop-blur-sm shadow-sm">
        <div className="mx-auto flex max-w-5xl items-center justify-between px-6 py-3">
          {logoUrl ? (
            <Image src={logoUrl} alt={businessName} width={110} height={38} className="h-9 w-auto object-contain" />
          ) : (
            <span className="text-lg font-black">{businessName}</span>
          )}
          <div className="flex items-center gap-2">
            {contacts.filter(c => c.type === "phone").slice(0, 1).map((c, i) => (
              <a key={i} href={`tel:${c.value}`}
                className="hidden items-center gap-1.5 text-sm font-semibold md:flex" style={{ color: accentColor }}>
                📱 {c.value}
              </a>
            ))}
            <a href={primaryCtaUrl} className="rounded-xl px-4 py-2.5 text-sm font-bold text-white transition-all hover:opacity-90 shadow-sm"
              style={{ background: accentColor }}>
              {primaryCtaLabel}
            </a>
