      <footer className="px-6 py-8 bg-white border-t border-slate-200 flex flex-wrap justify-between items-center gap-4">
        <p className="font-black text-slate-900">{businessName}</p>
        <p className="text-xs text-slate-300">PresenceCard</p>
      </footer>
    </main>
  );
}

