                {businessHours.map((h, i) => (
                  <div key={i} className="flex justify-between border-b border-white/5 py-2.5 text-sm">
                    <span className="uppercase tracking-wider text-white/40">{h.day.slice(0, 3)}</span>
                    <span className="font-mono text-white">{h.isClosed ? "—" : `${h.open}–${h.close}`}</span>
                  </div>
                ))}
              </div>
            </div>
          )}
          <div>
            <h2 className="mb-6 text-2xl font-black uppercase tracking-wide" style={{ color: accentColor }}>Find Us</h2>
            <div className="space-y-3">
              {contacts.map((c, i) => (
                <a key={i} href={contactHref(c.type, c.value)}
                  className="block text-sm text-white/50 hover:text-white transition-colors">{c.value}</a>
              ))}
              <div className="flex flex-wrap gap-3 pt-2">
                {socialLinks.map((s, i) => (
                  <a key={i} href={s.url} target="_blank" rel="noopener noreferrer"
                    className="text-xs uppercase tracking-widest transition-colors hover:text-white"
                    style={{ color: `${accentColor}70` }}>
                    {s.label ?? s.platform}
                  </a>
                ))}
              </div>
            </div>
          </div>
        </div>
      </section>

      <footer className="border-t border-white/5 px-6 py-8 text-center">
        <p className="text-xs tracking-widest text-white/15 uppercase">PresenceCard</p>
      </footer>
    </main>
  );
}

// ─────────────────────────────────────────────────────────────────────────────
// VAULT — Ultra-premium financial / legal / luxury, gold + deep black
// Research: Rolls-Royce, Goldman Sachs, Hermès, elite private banking websites
// ─────────────────────────────────────────────────────────────────────────────

export function VaultBusiness({ data, accentColor = "#d4af37" }: BizProps) {
  const {
    businessName, tagline, description, logoUrl,
    services, contacts, testimonials, faq, socialLinks,
    primaryCtaLabel, primaryCtaUrl, certifications, founded, industry,
  } = data;

  const gold = accentColor;

  return (
    <main className="min-h-screen text-neutral-200" style={{
      background: "linear-gradient(160deg, #080808 0%, #0a0a09 60%, #070707 100%)",
    }}>

      {/* Header */}
      <header className="border-b px-8 py-5" style={{ borderColor: `${gold}18` }}>
        <div className="mx-auto flex max-w-4xl items-center justify-between">
          {logoUrl ? (
            <Image src={logoUrl} alt={businessName} width={100} height={34}
              className="h-8 w-auto object-contain opacity-90" />
          ) : (
            <div>
              {founded && (
                <p className="text-xs uppercase tracking-[0.3em] mb-0.5" style={{ color: `${gold}60` }}>
                  Est. {founded}
                </p>
              )}
              <span className="text-base font-bold tracking-wider text-neutral-200">{businessName}</span>
            </div>
          )}
          <a href={primaryCtaUrl} className="border px-5 py-2 text-xs font-semibold uppercase tracking-widest transition-all hover:text-black"
            style={{ borderColor: `${gold}50`, color: gold, backgroundImage: "none" }}
            onMouseEnter={e => { (e.currentTarget as HTMLAnchorElement).style.background = gold; (e.currentTarget as HTMLAnchorElement).style.color = "#000"; }}
            onMouseLeave={e => { (e.currentTarget as HTMLAnchorElement).style.background = "transparent"; (e.currentTarget as HTMLAnchorElement).style.color = gold; }}>
            {primaryCtaLabel}
          </a>
        </div>
      </header>

      {/* Hero */}
      <section className="px-8 py-28 border-b" style={{ borderColor: `${gold}12` }}>
        <div className="mx-auto max-w-3xl">
          <div className="mb-6 h-px w-16" style={{ background: gold }} />
          {industry && (
            <p className="mb-2 text-xs uppercase tracking-[0.4em] text-neutral-600">{industry}</p>
          )}
          <h1 className="text-5xl font-bold leading-tight tracking-tight md:text-7xl" style={{ color: "#e8e0d5" }}>
            {businessName}
          </h1>
          <p className="mt-5 text-2xl font-light" style={{ color: gold }}>{tagline}</p>
          <p className="mt-5 max-w-2xl text-base leading-relaxed text-neutral-500">{description}</p>
          {certifications && certifications.length > 0 && (
            <div className="mt-7 flex flex-wrap gap-3">
              {certifications.map((c, i) => (
                <span key={i} className="border px-4 py-1.5 text-xs uppercase tracking-wider text-neutral-500"
                  style={{ borderColor: `${gold}25` }}>
                  {c}
                </span>
              ))}
            </div>
          )}
        </div>
      </section>

      {/* Services — Roman numeral list */}
      <section className="px-8 py-24 border-b" style={{ borderColor: `${gold}10` }}>
        <div className="mx-auto max-w-3xl">
          <p className="mb-10 text-xs uppercase tracking-[0.4em]" style={{ color: `${gold}70` }}>
            Practice Areas
          </p>
          <div className="space-y-10">
            {services.map((s, i) => (
              <div key={i} className="flex gap-8 pb-10 border-b last:border-0 last:pb-0" style={{ borderColor: `${gold}08` }}>
                <span className="shrink-0 text-lg font-light w-10 text-right" style={{ color: `${gold}40` }}>
                  {String(i + 1).padStart(2, "0")}
                </span>
                <div className="flex-1">
                  <h3 className="text-xl font-bold tracking-wide" style={{ color: "#e8e0d5" }}>{s.title}</h3>
                  {s.price && (
                    <p className="mt-1 text-sm font-semibold" style={{ color: gold }}>
                      {s.price}{s.priceNote && ` · ${s.priceNote}`}
                    </p>
                  )}
                  <p className="mt-2 text-sm leading-relaxed text-neutral-600">{s.description}</p>
                  {s.features && (
                    <ul className="mt-3 space-y-1">
                      {s.features.map((f, j) => (
                        <li key={j} className="flex items-center gap-2 text-xs text-neutral-700">
                          <span style={{ color: `${gold}60` }}>—</span> {f}
                        </li>
                      ))}
                    </ul>
                  )}
                </div>
              </div>
            ))}
          </div>
        </div>
      </section>

      {/* Testimonials — editorial pull quotes */}
      {testimonials && testimonials.length > 0 && (
        <section className="px-8 py-24 border-b" style={{ borderColor: `${gold}10` }}>
          <div className="mx-auto max-w-3xl">
            <p className="mb-10 text-xs uppercase tracking-[0.4em]" style={{ color: `${gold}70` }}>
              Testimonials
            </p>
            <div className="space-y-12">
              {testimonials.slice(0, 3).map((t, i) => (
                <div key={i} className="border-l-2 pl-8" style={{ borderColor: gold }}>
                  <p className="text-xl font-light leading-relaxed italic" style={{ color: "#c9b99a" }}>
                    &ldquo;{t.text}&rdquo;
                  </p>
                  <p className="mt-4 text-xs uppercase tracking-widest" style={{ color: `${gold}60` }}>
                    — {t.author}
                  </p>
                </div>
              ))}
            </div>
          </div>
        </section>
      )}

      {/* FAQ */}
      {faq && faq.length > 0 && (
        <section className="px-8 py-24 border-b" style={{ borderColor: `${gold}10` }}>
          <div className="mx-auto max-w-3xl">
            <p className="mb-10 text-xs uppercase tracking-[0.4em]" style={{ color: `${gold}70` }}>Common Questions</p>
            <div className="space-y-6">
              {faq.map((item, i) => (
                <details key={i} className="group border-b pb-6" style={{ borderColor: `${gold}08` }}>
                  <summary className="flex cursor-pointer items-center justify-between font-semibold list-none"
                    style={{ color: "#e8e0d5" }}>
                    {item.question}
                    <span className="ml-4 shrink-0 text-neutral-700 transition-transform group-open:rotate-180">▾</span>
                  </summary>
                  <p className="mt-4 text-sm leading-relaxed text-neutral-600">{item.answer}</p>
                </details>
              ))}
            </div>
          </div>
        </section>
      )}

      {/* Contact */}
      <section className="px-8 py-24">
        <div className="mx-auto max-w-3xl">
          <p className="mb-8 text-xs uppercase tracking-[0.4em]" style={{ color: `${gold}70` }}>Contact</p>
          <div className="grid gap-3 sm:grid-cols-2">
            {contacts.map((c, i) => (
              <a key={i} href={contactHref(c.type, c.value)}
                className="group flex items-center gap-3 border p-4 transition-all hover:border-neutral-700"
                style={{ borderColor: `${gold}12` }}>
                <span className="text-lg">
                  {c.type === "email" ? "✉️" : c.type === "phone" ? "📱" : c.type === "address" ? "📍" : "🌐"}
                </span>
                <div>
                  <p className="text-xs uppercase tracking-wider text-neutral-700">{c.label ?? c.type}</p>
                  <p className="text-sm text-neutral-400">{c.value}</p>
                </div>
              </a>
            ))}
          </div>
          <div className="mt-6 flex flex-wrap gap-4">
            {socialLinks.map((s, i) => (
              <a key={i} href={s.url} target="_blank" rel="noopener noreferrer"
                className="text-xs uppercase tracking-widest transition-colors hover:text-white"
                style={{ color: `${gold}50` }}>
                {s.label ?? s.platform}
              </a>
            ))}
          </div>
        </div>
      </section>

      <footer className="border-t px-8 py-8 flex justify-between items-center" style={{ borderColor: `${gold}10` }}>
        <span className="text-xs uppercase tracking-widest" style={{ color: `${gold}30` }}>{businessName}</span>
        <span className="text-xs text-neutral-900">PresenceCard</span>
      </footer>
    </main>
  );
}
